113	/**
114	 * 非流式 AI 調用
115	 */
116	async function callNonStream(
117	  context: AICallContext,
118	  mIdx: number,
119	  idx: number,
120	  config: CallConfig,
121	  signature: string,
122	) {
123	  context.messages.value[mIdx][idx] = {
124	    role: Role.Assistant,
125	    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
126	    timestamp: Date.now(),
127	    status: Status.Pending,
128	  };
129	
130	  const res = await fetch(getApiUrl("/api/run?stream=false"), {
131	    method: "POST",
132	    headers: {
133	      "Content-Type": "application/json",
134	      Authorization: signature,
135	      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
136	    },
137	    body: JSON.stringify({ input_value: config.content }),
138	  });
139	
140	  if (!res.ok) {
141	    const errorText = await res.text();
142	    if (isQuotaErrorText(res.status, errorText)) {
143	      throw new QuotaExceededError(errorText);
144	    }
145	    throw new Error(errorText);
146	  }
147	
148	  const data = await res.json();
149	
150	  if (data.detail) {
151	    const detailStr = String(data.detail);
152	    if (TRANSIENT_AI_ERROR_PATTERN.test(detailStr)) {
153	      throw new QuotaExceededError(detailStr);
154	    }
155	    throw new Error(detailStr);
156	  }
157	
158	  data.outputs?.[0].outputs.forEach((output: any, i: number) => {
159	    context.messages.value[mIdx][idx + i] = {
160	      role: Role.Assistant,
161	      content: output.artifacts.message,
162	      timestamp: Date.now(),
163	      status: Status.End,
164	      source: config.flowId === "5"
165	        ? output.results.message.data.properties.source.source
166	        : "",
167	    };
168	  });
169	}
