171	type SseStreamPayload = {
172	  delta?: string;
173	  source?: string;
174	  done?: boolean;
175	  error?: string;
176	};
177	
178	function isQuotaErrorText(status: number, text: string): boolean {
179	  return status === 429 || status === 503 || TRANSIENT_AI_ERROR_PATTERN.test(text);
180	}
181	
182	/** 把一行文字解析成 SSE payload；不是 `data: ` 開頭的行（例如空白分隔行）回傳 null */
183	function parseSseLine(rawLine: string): SseStreamPayload | null {
184	  const line = rawLine.trim();
185	  if (!line.startsWith("data: ")) return null;
186	  return JSON.parse(line.slice("data: ".length));
187	}
188	
189	/** 讀取一個 SSE response body，逐段解析出 payload 陣列（可能因為 chunk 邊界而一次拿到多個或零個） */
190	async function readSseChunk(
191	  reader: ReadableStreamDefaultReader<Uint8Array>,
192	  decoder: TextDecoder,
193	  bufferRef: { value: string },
194	): Promise<{ done: boolean; payloads: SseStreamPayload[] }> {
195	  const { done, value } = await reader.read();
196	  if (done) return { done: true, payloads: [] };
197	
198	  bufferRef.value += decoder.decode(value, { stream: true });
199	  const events = bufferRef.value.split("\n\n");
200	  bufferRef.value = events.pop() ?? ""; // 最後一段可能還不完整，留到下一輪繼續接
201	
202	  const payloads = events
203	    .map(parseSseLine)
204	    .filter((p): p is SseStreamPayload => p !== null);
205	  return { done: false, payloads };
206	}
207	
208	type StreamAccumulator = {
209	  content: string;
210	  source: string;
211	  hasReceivedContent: boolean;
212	};
213	
214	/** 套用單一 SSE payload 到累積狀態，並即時更新畫面上的訊息內容 */
215	function applyStreamPayload(
216	  payload: SseStreamPayload,
217	  acc: StreamAccumulator,
218	  context: AICallContext,
219	  mIdx: number,
220	  idx: number,
221	) {
222	  if (payload.error) throw new Error(payload.error);
223	
224	  if (payload.delta) {
225	    acc.content += payload.delta;
226	    acc.hasReceivedContent = true;
227	    context.messages.value[mIdx][idx] = {
228	      role: Role.Assistant,
229	      content: acc.content,
230	      timestamp: Date.now(),
231	      status: Status.Receiving,
232	    };
233	  }
234	
235	  if (payload.done) acc.source = payload.source ?? "";
236	}
237	
238	/** 讀完整個 SSE response body，過程中即時更新畫面，回傳最終累積狀態 */
239	async function consumeSseStream(
240	  res: Response,
241	  context: AICallContext,
242	  mIdx: number,
243	  idx: number,
244	): Promise<StreamAccumulator> {
245	  const reader = res.body!.getReader();
246	  const decoder = new TextDecoder("utf-8");
247	  const bufferRef = { value: "" };
248	  const acc: StreamAccumulator = { content: "", source: "", hasReceivedContent: false };
249	
250	  while (true) {
251	    const { done, payloads } = await readSseChunk(reader, decoder, bufferRef);
252	    if (done) break;
253	    for (const payload of payloads) {
254	      applyStreamPayload(payload, acc, context, mIdx, idx);
255	    }
256	  }
257	
258	  return acc;
259	}
260	
261	/**
262	 * 串流 AI 調用（flowId=6：Gemini File Search RAG；flowId=7／9：學習規劃探索助手；
263	 * flowId=8：未來教室設備支援助理）
264	 * 後端以 SSE 逐段吐出文字，格式為 `data: {delta, source, done, error}\n\n`
265	 */
266	async function callStream(
267	  context: AICallContext,
268	  mIdx: number,
269	  idx: number,
270	  config: CallConfig,
271	  signature: string,
272	) {
273	  context.messages.value[mIdx][idx] = {
274	    role: Role.Assistant,
275	    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
276	    timestamp: Date.now(),
277	    status: Status.Pending,
278	  };
279	
280	  const res = await fetch(getApiUrl("/api/run?stream=true"), {
281	    method: "POST",
282	    headers: {
283	      "Content-Type": "application/json",
284	      Authorization: signature,
285	      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
286	    },
287	    body: JSON.stringify({
288	      input_value: config.content,
289	      ...(config.history ? { history: config.history } : {}),
290	      ...(config.image ? { image: config.image } : {}),
291	      ...(config.model ? { model: config.model } : {}),
292	    }),
293	  });
294	
295	  if (!res.ok || !res.body) {
296	    const errorText = await res.text();
297	    if (isQuotaErrorText(res.status, errorText)) {
298	      throw new QuotaExceededError(errorText);
299	    }
300	    throw new Error(errorText || `串流請求失敗 (${res.status})`);
301	  }
302	
303	  const { content, source, hasReceivedContent } = await consumeSseStream(
304	    res,
305	    context,
306	    mIdx,
307	    idx,
308	  );
309	
310	  context.messages.value[mIdx][idx] = {
311	    role: Role.Assistant,
312	    content: hasReceivedContent
313	      ? content
314	      : "目前找不到與這個問題相關的資料，請確認文件是否已上傳完成，或換個問法再試一次。",
315	    timestamp: Date.now(),
316	    status: Status.End,
317	    source,
318	  };
319	}
320	
321	/**
322	 * AI 調用主函數（包含錯誤處理和額度用光自動切換）
323	 */
324	export async function callAI(
325	  context: AICallContext,
326	  mIdx: number,
327	  idx: number,
328	  config: CallConfig,
329	  _stream: boolean = false,
330	) {
331	  try {
332	    await executeAICall(context, mIdx, idx, config);
333	  } catch (error) {
334	    // 如果是額度用光且當前是 flow 0，自動切換到 flow 1
335	    if (
336	      error instanceof QuotaExceededError &&
337	      config.flowId === "0" &&
338	      !context.route.query.flow
339	    ) {
340	      console.log("額度用光，自動切換到 flow 1");
341	      const fallbackConfig = { ...config, flowId: "1" };
342	      try {
343	        await executeAICall(context, mIdx, idx, fallbackConfig);
344	        return;
345	      } catch (fallbackError) {
346	        // flow 1 也失敗，顯示錯誤
347	        console.error(fallbackError);
348	        showErrorMessage(context.messages, mIdx, idx, fallbackError);
349	        return;
350	      }
351	    }
352	
353	    // 其他錯誤
354	    console.error(error);
355	    showErrorMessage(context.messages, mIdx, idx, error);
356	  }
357	}
