4	export interface FileUploadContext {
5	  jwtToken: Ref<string>;
6	}
7	
8	const MAX_FILE_SIZE_BYTES = 50 * 1024 * 1024; // 50MB，需與後端 GeminiController 的限制一致
9	
10	/**
11	 * 上傳文件到 flowId=6 用的個人知識庫（Gemini File Search）
12	 * 回傳後端的提示訊息（例如「文件上傳中，索引可能需要幾分鐘」）
13	 */
14	export async function uploadFile(
15	  context: FileUploadContext,
16	  file: File,
17	): Promise<string> {
18	  if (file.size > MAX_FILE_SIZE_BYTES) {
19	    throw new Error("檔案大小超過 50MB 上限");
20	  }
21	
22	  const formData = new FormData();
23	  formData.append("file", file, file.name);
24	
25	  const res = await fetch(getApiUrl("/api/gemini/upload"), {
26	    method: "POST",
27	    headers: {
28	      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
29	    },
30	    body: formData,
31	  });
32	
33	  if (!res.ok) {
34	    const errorText = await res.text();
35	    throw new Error(errorText || `上傳失敗 (${res.status})`);
36	  }
37	
38	  const data = await res.json();
39	  return data.message ?? "文件上傳中，索引可能需要幾分鐘，完成後即可查詢。";
40	}
