18	export function getApiUrl(path: string): string {
19	  const API_URL = import.meta.env.VITE_API_URL;
20	  const normalizedPath = path.startsWith("/") ? path : `/${path}`;
21	  if (!API_URL?.trim()) return normalizedPath;
22	  const baseUrl = API_URL.replace(/\/$/, "");
23	  return `${baseUrl}${normalizedPath}`;
24	}
