1	import { type Ref } from "vue";
2	import { getApiUrl } from "@/lib/utils";
3	import { encryptSignature } from "./useAICall";
4	
5	export interface AudioTranscriptionContext {
6	  publicKey: string;
7	  fingerprint: Ref<string> | undefined;
8	  jwtToken: Ref<string>;
9	  isTranscribing: Ref<boolean>;
10	}
