12	/**
13	 * 處理音頻轉錄
14	 */
15	export async function handleAudioTranscription(
16	  context: AudioTranscriptionContext,
17	  audioBlob: Blob,
18	): Promise<string> {
19	  try {
20	    context.isTranscribing.value = true;
21	    const timestamp = Date.now();
22	    const config = {
23	      flowId: "0",
24	    };
25	
26	    if (audioBlob.size < 1000) {
27	      throw new Error("錄音太短，請錄製較長的語音");
28	    }
29	
30	    const signature = await encryptSignature(
31	      context.publicKey,
32	      `${context.fingerprint?.value} ${timestamp} ${config.flowId}`,
33	    );
34	
35	    const formData = new FormData();
36	    // Determine filename based on MIME type
37	    let fileName = "audio.webm";
38	    if (audioBlob.type.includes("wav")) fileName = "audio.wav";
39	    else if (audioBlob.type.includes("mp3")) fileName = "audio.mp3";
40	    else if (audioBlob.type.includes("mp4")) fileName = "audio.mp4";
41	    else if (audioBlob.type.includes("ogg")) fileName = "audio.ogg";
42	
43	    formData.append("audio", audioBlob, fileName);
44	
45	    // Add timeout
46	    const controller = new AbortController();
47	    const timeoutId = setTimeout(() => {
48	      controller.abort();
49	    }, 480000); // 480 second timeout (8 minutes)
50	
51	    try {
52	      const response = await fetch(getApiUrl("/api/whisper/transcribe"), {
53	        method: "POST",
54	        headers: {
55	          Authorization: signature,
