70	          console.error(
71	            `Transcription error (${response.status}):`,
72	            errorMessage,
73	          );
74	        } catch (parseError) {
75	          console.error("Transcription error: Failed to parse error response");
76	          errorMessage = `HTTP error! status: ${response.status}`;
77	        }
78	
79	        throw new Error(
80	          errorMessage || `HTTP error! status: ${response.status}`,
81	        );
82	      }
83	
84	      const data = await response.json();
85	
86	      // Handle the text field that includes "text: " prefix
87	      let transcribedText = data.text || "";
88	      if (transcribedText.startsWith("text: ")) {
89	        transcribedText = transcribedText.substring(6);
90	      }
91	
92	      if (transcribedText && transcribedText.trim()) {
93	        return transcribedText;
94	      } else {
95	        throw new Error("無法識別語音內容，請說話清晰一些並重試");
